  "timeline.safety.subtitle": "உங்கள் சேமிக்கப்பட்ட அனைத்து ஆவணங்களிலும் காணப்படும் மாதிரிகள், ஒன்றில் மட்டும் அல்ல. AI-உதவியுடன் இது ஒரு நோயறிதல் அல்ல — எப்போதும் உங்கள் மருத்துவரிடம் இவற்றைப் பற்றி விவாதிக்கவும்.",
